use super::*;
use std::{fs::OpenOptions,collections::BTreeMap};
use self::core::{canonical,hashes,wire::Capability};
pub(crate) struct Repository{pub(super) root:PathBuf,pub(super) policy:Policy,pub(super) clock:Clock,pub(super) gate:Mutex<()>}
impl Repository{
    pub fn new(root:PathBuf,policy:Policy)->Self{Self{root,policy,clock:Clock::system(),gate:Mutex::new(())}}
    pub(super) fn db(&self)->PathBuf{self.root.join("fiscal/repository.sqlite3")}
    pub(super) fn marker_for(&self,id:String)->Result<Marker>{Ok(Marker{version:1,purpose:"mx.nomina.fiscal-repository.v1".into(),repository_id:id,channel:self.policy.channel.clone(),bootstrap_sha256:self.policy.hash()?})}
    pub(super) fn validate_marker(&self,m:&Marker)->Result<()>{if uuid::Uuid::parse_str(&m.repository_id).is_err()||*m!=self.marker_for(m.repository_id.clone())?{return Err(fail("REPOSITORY_IDENTITY_MISMATCH"));}Ok(())}
    pub(super) fn namespace(&self)->Result<()>{paths::directory(&self.root)?;let dir=self.root.join("fiscal");if paths::present(&dir)?{paths::directory(&dir)?;for e in fs::read_dir(&dir)?{let e=e?;if !["repository.sqlite3","repository.sqlite3-journal","repository.sqlite3-wal","repository.sqlite3-shm","backups","recovery"].contains(&e.file_name().to_string_lossy().as_ref()){return Err(fail("RECOVERY_PENDING"));}let p=e.path();if e.file_name()=="backups"||e.file_name()=="recovery"{paths::directory(&p)?;}else{paths::regular(&p)?;}}}Ok(())}
    pub fn inspect_presence(&self)->Result<String>{paths::local_path(&self.root)?;if !paths::present(&self.root)?{return Ok("absent".into());}let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;self.presence()}
    fn presence(&self)->Result<String>{self.namespace()?;let intention=paths::present(&self.root.join("fiscal-initialization.json"))?;let complete=paths::present(&self.root.join("fiscal-initialized.json"))?;let db=paths::present(&self.db())?;let partial=paths::present(&self.root.join("fiscal-initialization.part"))?||paths::present(&self.root.join("fiscal-initialized.part"))?;
        if complete{if !intention{return Err(fail("REPOSITORY_IDENTITY_MISMATCH"));}let a=paths::marker(&self.root.join("fiscal-initialization.json"))?;let b=paths::marker(&self.root.join("fiscal-initialized.json"))?;self.validate_marker(&a)?;if a!=b{return Err(fail("REPOSITORY_IDENTITY_MISMATCH"));}if !db{return Err(fail("REPOSITORY_MISSING"));}if partial{return Err(fail("RECOVERY_PENDING"));}return Ok("existing".into());}
        if intention||partial{return Ok("initialization-pending".into());}if db||paths::present(&self.root.join("fiscal"))?{return Err(fail("ORPHANED_REPOSITORY"));}Ok("absent".into())
    }
    pub fn initialize_new(&self)->Result<Status>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;paths::ensure_root(&self.root)?;let _lock=paths::lock(&self.root)?;if self.presence()?!="absent"{return Err(fail("INITIALIZATION_NOT_ALLOWED"));}
        point("initialization-before-intention")?;let m=self.marker_for(uuid::Uuid::new_v4().to_string())?;paths::publish(&self.root.join("fiscal-initialization.json"),&canonical::bytes(&m)?)?;point("initialization-intention")?;
        fs::create_dir(self.root.join("fiscal"))?;paths::private_directory(&self.root.join("fiscal"))?;let f=OpenOptions::new().create_new(true).write(true).open(self.db())?;f.sync_all()?;drop(f);point("initialization-reserved")?;
        let mut c=schema::open(&self.db(),false)?;c.execute_batch("PRAGMA page_size=4096; PRAGMA journal_mode=DELETE; PRAGMA max_page_count=262144;")?;
        let tx=c.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;schema::create(&tx)?;point("initialization-schema")?;tx.execute("INSERT INTO repository_meta VALUES(1,?1,?2,?3,0,?4,'')",params![m.repository_id,m.channel,m.bootstrap_sha256,"0".repeat(64)])?;point("initialization-before-commit")?;tx.commit()?;point("initialization-after-commit")?;drop(c);
        point("initialization-verifying")?;let c=schema::open(&self.db(),false)?;replay::rebuild(&c,&self.policy,&m)?;drop(c);point("initialization-before-complete")?;paths::publish(&self.root.join("fiscal-initialized.json"),&canonical::bytes(&m)?)?;point("initialization-complete")?;self.status_locked()
    }
    pub fn recover_initialization(&self)->Result<Status>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let p=self.presence()?;if p=="existing"{return self.status_locked();}if p!="initialization-pending"{return Err(fail("RECOVERY_NOT_ALLOWED"));}
        let m=paths::marker(&self.root.join("fiscal-initialization.json"))?;self.validate_marker(&m)?;if !paths::present(&self.db())?{return Err(fail("INITIALIZATION_PENDING"));}let c=schema::open(&self.db(),false)?;replay::rebuild(&c,&self.policy,&m).map_err(|_|fail("INITIALIZATION_PENDING"))?;drop(c);
        let expected=canonical::bytes(&m)?;let partial=self.root.join("fiscal-initialized.part");if paths::present(&partial)?{if paths::bounded(&partial,limits::MANIFEST)?!=expected{return Err(fail("RECOVERY_PENDING"));}fs::remove_file(partial)?;}
        paths::publish(&self.root.join("fiscal-initialized.json"),&expected)?;self.status_locked()
    }
    pub(super) fn existing(&self)->Result<(Connection,Marker)>{if self.presence()?!="existing"{return Err(fail("INITIALIZATION_PENDING"));}let m=paths::marker(&self.root.join("fiscal-initialized.json"))?;let c=schema::open(&self.db(),false)?;let c=migration::ensure(self,c,&m)?;Ok((c,m))}
    pub fn open_existing(&self)->Result<Status>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;self.status_locked()}
    pub fn inspect_recovery(&self)->Result<String>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let presence=self.presence()?;if presence!="existing"{return Ok(presence);}let(c,m)=self.existing()?;replay::rebuild(&c,&self.policy,&m)?;recovery::check_pending(self,&c,&m)?;Ok("verified-no-recovery-pending".into())}
    fn status_locked(&self)->Result<Status>{let (c,m)=self.existing()?;let view=replay::rebuild(&c,&self.policy,&m)?;let (id,generation,_,max)=meta(&c)?;let now=self.clock.now()?;let validity=if self.policy.channel=="production"&&self.policy.roots.is_empty(){"production-bootstrap-missing"}else if view.signed.is_none(){"metadata-required"}else if clock::check(&now,&max).is_err(){"clock-rollback"}else if view.trust.current(&now).is_err(){"expired"}else{"current"};Ok(Status{repository_id:id,generation,trust_epoch:view.trust.epoch(),root_version:view.trust.root_version(),validity:validity.into(),max_observed_utc:max,installations:count(&c,"installations")?,sqlite_version:c.query_row("SELECT sqlite_version()",[],|r|r.get(0))?})}
    pub fn operation_status(&self,id:&str)->Result<Option<Receipt>>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let(c,m)=self.existing()?;replay::rebuild(&c,&self.policy,&m)?;let b:Option<Vec<u8>>=c.query_row("SELECT receipt FROM operations WHERE id=?1",[id],|r|r.get(0)).optional()?;b.map(|b|decode(&b)).transpose()}
    pub(super) fn mutate<F>(&self,id:&str,expected:u64,build:F)->Result<Receipt> where F:FnOnce(&Connection)->Result<(Action,BTreeMap<(String,String),Vec<u8>>)>{
        if uuid::Uuid::parse_str(id).is_err(){return Err(fail("INVALID_OPERATION_ID"));}let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let(mut c,m)=self.existing()?;
        let tx=c.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;let mut view=replay::rebuild(&tx,&self.policy,&m)?;recovery::check_pending(self,&tx,&m)?;let(action,pending)=build(&tx)?;let request=replay::intent(&action)?;
        if let Some((old,b))=tx.query_row("SELECT request_sha256,receipt FROM operations WHERE id=?1",[id],|r|Ok((r.get::<_,String>(0)?,r.get::<_,Vec<u8>>(1)?))).optional()?{if old!=request{return Err(fail("OPERATION_CONFLICT"));}return decode(&b);}
        let(_,generation,previous,max)=meta(&tx)?;if expected!=generation{return Err(fail("STALE_GENERATION"));}limits::budget(generation,1,limits::OPERATIONS)?;let seq=generation+1;let now=self.clock.now()?;clock::check(&now,&max)?;
        let body=canonical::bytes(&action)?;limits::size(&body,limits::MANIFEST)?;let receipt=activation::receipt(&action,id,seq);let rb=canonical::bytes(&receipt)?;let hash=replay::entry(id,seq,&request,&now,&body,&previous,&rb)?;
        // Verification precedes even the audit-row write. FK enforcement is
        // deferred, never disabled: all referenced operation rows exist at commit.
        tx.execute_batch("PRAGMA defer_foreign_keys=ON;")?;
        let source=replay::Source{connection:&tx,pending};let produced=replay::apply(&tx,&source,&mut view,&action,id,seq,&now,&self.policy)?;if produced!=receipt{return Err(fail("INTERNAL_INVARIANT"));}
        tx.execute("INSERT INTO operations VALUES(?1,?2,?3,?4,?5,?6,?7,?8)",params![id,seq,request,now,body,previous,hash,rb])?;
        tx.execute("UPDATE repository_meta SET generation=?1,head=?2,max_utc=?3 WHERE id=1",params![seq,hash,now])?;point("operation-before-commit")?;
        if let Err(cause)=tx.commit(){drop(c);return match self.resolve_commit(id,&request){Err(e) if e.code=="NOT_COMMITTED"=>Err(cause.into()),result=>result};}
        if point("operation-after-commit").is_err(){drop(c);return self.resolve_commit(id,&request);}drop(c);self.resolve_commit(id,&request)
    }
    fn resolve_commit(&self,id:&str,request:&str)->Result<Receipt>{let(c,m)=self.existing().map_err(|_|fail("COMMIT_OUTCOME_UNKNOWN"))?;replay::rebuild(&c,&self.policy,&m).map_err(|_|fail("COMMITTED_RECOVERY_PENDING"))?;let result:Option<(String,Vec<u8>)>=c.query_row("SELECT request_sha256,receipt FROM operations WHERE id=?1",[id],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(|_|fail("COMMIT_OUTCOME_UNKNOWN"))?;match result{Some((h,b)) if h==request=>decode(&b).map_err(|_|fail("COMMITTED_RECOVERY_PENDING")),Some(_)=>Err(fail("OPERATION_CONFLICT")),None=>Err(fail("NOT_COMMITTED"))}}
    pub fn accept_trust_episode(&self,id:&str,generation:u64,updates:&[Vec<u8>])->Result<Receipt>{if updates.is_empty()||updates.len()>16{return Err(fail("TRUST_TRANSITION_LIMIT"));}for b in updates{limits::size(b,limits::TRUST_BYTES)?;}let documents=updates.iter().map(|b|hashes::sha256(b)).collect::<Vec<_>>();let pending=documents.iter().zip(updates).map(|(h,b)|(("trust_documents".into(),h.clone()),b.clone())).collect();self.mutate(id,generation,move |_|Ok((Action::Trust{documents},pending)))}
    pub fn record_verified_installation(&self,id:&str,generation:u64,bytes:&[u8],operations:&[Capability])->Result<Receipt>{limits::size(bytes,limits::OBJECT_BYTES)?;let hash=hashes::sha256(bytes);let mut pending=BTreeMap::new();pending.insert(("containers".into(),hash.clone()),bytes.to_vec());let caps=operations.to_vec();self.mutate(id,generation,move |c|{let installation=c.query_row("SELECT id FROM installations WHERE container_sha256=?1",[&hash],|r|r.get::<_,String>(0)).optional()?.unwrap_or_else(||uuid::Uuid::new_v4().to_string());Ok((Action::Install{envelope_sha256:hash,operations:caps,installation_id:installation,admission_id:uuid::Uuid::new_v4().to_string()},pending))})}
    pub fn record_rollback_evidence(&self,id:&str,generation:u64,bytes:&[u8],target:&str,previous_floor:u64)->Result<Receipt>{limits::size(bytes,limits::TRUST_BYTES)?;let hash=hashes::sha256(bytes);let mut pending=BTreeMap::new();pending.insert(("rollback_documents".into(),hash.clone()),bytes.to_vec());let action=Action::Grant{document:hash,target:target.into(),previous_floor};self.mutate(id,generation,move |_|Ok((action,pending)))}
    pub fn read_original(&self,hash:&str)->Result<Vec<u8>>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let(c,m)=self.existing()?;replay::rebuild(&c,&self.policy,&m)?;replay::Source{connection:&c,pending:BTreeMap::new()}.load("containers",hash,limits::OBJECT_BYTES)}
    pub fn list_installations(&self,limit:u64,after:&str)->Result<Vec<(String,String)>>{limits::page(limit)?;let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let(c,m)=self.existing()?;replay::rebuild(&c,&self.policy,&m)?;let mut s=c.prepare("SELECT id,container_sha256 FROM installations WHERE id>?1 ORDER BY id LIMIT ?2")?;let result=s.query_map(params![after,limit],|r|Ok((r.get(0)?,r.get(1)?)))?.collect::<rusqlite::Result<Vec<_>>>()?;Ok(result)}
    pub fn create_verified_copy(&self)->Result<PathBuf>{let _gate=self.gate.lock().map_err(|_|fail("LOCK_POISONED"))?;let _lock=paths::lock(&self.root)?;let(mut c,m)=self.existing()?;let tx=c.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;replay::rebuild(&tx,&self.policy,&m)?;let result=recovery::backup(self,&tx,&m)?;tx.rollback()?;Ok(result)}
}
fn decode<T:serde::de::DeserializeOwned+serde::Serialize>(b:&[u8])->Result<T>{limits::size(b,limits::MANIFEST)?;let v=core::strict_json::parse_with_limit(b,limits::MANIFEST as usize)?;canonical::require_wire(b,&v)?;Ok(core::decode_closed(&v)?)}
